// File: p2p-kids-marketplace/src/services/pushDelivery.ts
// Centralized Push Notification Delivery Engine
// Handles rate limiting, quiet hours, deduplication, retries, and receipts

import { Expo, ExpoPushMessage, ExpoPushTicket, ExpoPushReceipt } from 'expo-server-sdk';
import { supabase } from '../config/supabase';

const expo = new Expo();

export interface PushDeliveryOptions {
  userId: string;
  notificationId?: string;
  title: string;
  body: string;
  data?: Record<string, any>;
  type: string; // e.g., 'sp_earned', 'badge_earned'
  fingerprint?: string; // For deduplication (can be hash of type + key data)
  critical?: boolean; // If true, bypass quiet hours and rate limits
  sound?: 'default' | null;
  badge?: number;
  priority?: 'default' | 'normal' | 'high';
}

export interface PushDeliveryResult {
  success: boolean;
  sent: boolean; // false if rate-limited or in quiet hours
  rateLimited?: boolean;
  inQuietHours?: boolean;
  duplicate?: boolean;
  error?: string;
  ticketId?: string;
  receipts?: ExpoPushReceipt[];
}

/**
 * Check if user can receive push notification (not rate-limited)
 */
async function checkRateLimit(userId: string): Promise<boolean> {
  try {
    const { data, error } = await supabase.rpc('check_push_rate_limit', {
      p_user_id: userId,
    });

    if (error) {
      console.error('[pushDelivery] Rate limit check error:', error);
      return false; // Fail closed - don't send if check fails
    }

    return data === true;
  } catch (err) {
    console.error('[pushDelivery] Rate limit check exception:', err);
    return false;
  }
}

/**
 * Check if user is currently in quiet hours
 */
async function checkQuietHours(userId: string): Promise<boolean> {
  try {
    const { data, error } = await supabase.rpc('is_in_quiet_hours', {
      p_user_id: userId,
    });

    if (error) {
      console.error('[pushDelivery] Quiet hours check error:', error);
      return false; // Assume not in quiet hours if check fails
    }

    return data === true;
  } catch (err) {
    console.error('[pushDelivery] Quiet hours check exception:', err);
    return false;
  }
}

/**
 * Check if notification is a duplicate (within 5-minute window)
 */
async function checkDuplicate(
  userId: string,
  type: string,
  fingerprint: string
): Promise<boolean> {
  try {
    const { data, error } = await supabase.rpc('is_duplicate_notification', {
      p_user_id: userId,
      p_notification_type: type,
      p_fingerprint: fingerprint,
    });

    if (error) {
      console.error('[pushDelivery] Duplicate check error:', error);
      return false; // Assume not duplicate if check fails
    }

    return data === true;
  } catch (err) {
    console.error('[pushDelivery] Duplicate check exception:', err);
    return false;
  }
}

/**
 * Record notification for deduplication tracking
 */
async function recordDeduplication(
  userId: string,
  type: string,
  fingerprint: string
): Promise<void> {
  try {
    const { error } = await supabase.rpc('record_notification_dedup', {
      p_user_id: userId,
      p_notification_type: type,
      p_fingerprint: fingerprint,
    });

    if (error) {
      console.error('[pushDelivery] Failed to record deduplication:', error);
    }
  } catch (err) {
    console.error('[pushDelivery] Record deduplication exception:', err);
  }
}

/**
 * Log push delivery attempt
 */
async function logDelivery(
  userId: string,
  notificationId: string | undefined,
  pushTokenId: string,
  ticketId: string | null,
  receiptStatus: string = 'ok',
  receiptMessage: string | null = null,
  receiptDetails: any = null,
  retryCount: number = 0
): Promise<void> {
  try {
    await supabase.rpc('log_push_delivery', {
      p_user_id: userId,
      p_notification_id: notificationId || null,
      p_push_token_id: pushTokenId,
      p_expo_receipt_id: ticketId,
      p_receipt_status: receiptStatus,
      p_receipt_message: receiptMessage,
      p_receipt_details: receiptDetails ? JSON.parse(JSON.stringify(receiptDetails)) : null,
      p_retry_count: retryCount,
    });
  } catch (err) {
    console.error('[pushDelivery] Failed to log delivery:', err);
  }
}

/**
 * Add failed notification to retry queue
 */
async function addToRetryQueue(
  notificationId: string,
  userId: string,
  error: string,
  errorDetails: any = null
): Promise<void> {
  try {
    await supabase.rpc('add_to_retry_queue', {
      p_notification_id: notificationId,
      p_user_id: userId,
      p_error: error,
      p_error_details: errorDetails ? JSON.parse(JSON.stringify(errorDetails)) : null,
    });
  } catch (err) {
    console.error('[pushDelivery] Failed to add to retry queue:', err);
  }
}

/**
 * Remove notification from retry queue (after successful delivery)
 */
async function removeFromRetryQueue(notificationId: string): Promise<void> {
  try {
    await supabase.rpc('remove_from_retry_queue', {
      p_notification_id: notificationId,
    });
  } catch (err) {
    console.error('[pushDelivery] Failed to remove from retry queue:', err);
  }
}

/**
 * Get active push tokens for user
 */
async function getUserPushTokens(userId: string): Promise<Array<{ id: string; token: string }>> {
  try {
    const { data, error } = await supabase
      .from('push_tokens' as never)
      .select('id, token')
      .eq('user_id', userId);

    if (error) {
      console.error('[pushDelivery] Failed to get push tokens:', error);
      return [];
    }

    return (data || []) as Array<{ id: string; token: string }>;
  } catch (err) {
    console.error('[pushDelivery] Get push tokens exception:', err);
    return [];
  }
}

/**
 * Send push notification to user with rate limiting, quiet hours, and deduplication
 * 
 * @param options - Push delivery options
 * @returns Delivery result with success status and metadata
 */
export async function sendPushNotification(
  options: PushDeliveryOptions
): Promise<PushDeliveryResult> {
  const {
    userId,
    notificationId,
    title,
    body,
    data = {},
    type,
    fingerprint,
    critical = false,
    sound = 'default',
    badge,
    priority = 'default',
  } = options;

  // Generate fingerprint if not provided (hash of type + userId + current minute)
  const actualFingerprint =
    fingerprint ||
    `${type}-${userId}-${Math.floor(Date.now() / 60000)}`; // 1-minute window for auto-generated fingerprints

  try {
    // 1. Check deduplication (unless critical)
    if (!critical) {
      const isDuplicate = await checkDuplicate(userId, type, actualFingerprint);
      if (isDuplicate) {
        console.log(`[pushDelivery] Duplicate notification blocked: ${type} for user ${userId}`);
        return {
          success: true,
          sent: false,
          duplicate: true,
        };
      }
    }

    // 2. Check rate limit (unless critical)
    if (!critical) {
      const withinRateLimit = await checkRateLimit(userId);
      if (!withinRateLimit) {
        console.log(`[pushDelivery] Rate limit exceeded for user ${userId}`);
        return {
          success: true,
          sent: false,
          rateLimited: true,
        };
      }
    }

    // 3. Check quiet hours (unless critical)
    if (!critical) {
      const inQuietHours = await checkQuietHours(userId);
      if (inQuietHours) {
        console.log(`[pushDelivery] User ${userId} in quiet hours, notification deferred`);
        return {
          success: true,
          sent: false,
          inQuietHours: true,
        };
      }
    }

    // 4. Get user's push tokens
    const pushTokens = await getUserPushTokens(userId);
    if (pushTokens.length === 0) {
      console.warn(`[pushDelivery] No push tokens found for user ${userId}`);
      return {
        success: false,
        sent: false,
        error: 'No push tokens registered',
      };
    }

    // 5. Build push messages for all user's devices
    const messages: ExpoPushMessage[] = pushTokens
      .filter((pt) => Expo.isExpoPushToken(pt.token))
      .map((pt) => ({
        to: pt.token,
        sound: sound as 'default' | null,
        title,
        body,
        data: {
          ...data,
          notificationId,
          type,
        },
        badge,
        priority: priority as 'default' | 'normal' | 'high',
      }));

    if (messages.length === 0) {
      console.warn(`[pushDelivery] No valid Expo push tokens for user ${userId}`);
      return {
        success: false,
        sent: false,
        error: 'No valid Expo push tokens',
      };
    }

    // 6. Send push notifications
    const chunks = expo.chunkPushNotifications(messages);
    const tickets: ExpoPushTicket[] = [];

    for (const chunk of chunks) {
      try {
        const ticketChunk = await expo.sendPushNotificationsAsync(chunk);
        tickets.push(...ticketChunk);
      } catch (err) {
        console.error('[pushDelivery] Failed to send push notification chunk:', err);

        // Add to retry queue if notification ID provided
        if (notificationId) {
          await addToRetryQueue(
            notificationId,
            userId,
            err instanceof Error ? err.message : 'Unknown error',
            { chunk }
          );
        }
      }
    }

    // 7. Log delivery attempts
    for (let i = 0; i < tickets.length; i++) {
      const ticket = tickets[i];
      const pushToken = pushTokens[i];

      if (ticket.status === 'ok') {
        await logDelivery(
          userId,
          notificationId,
          pushToken.id,
          ticket.id,
          'ok',
          null,
          null,
          0
        );
      } else if (ticket.status === 'error') {
        await logDelivery(
          userId,
          notificationId,
          pushToken.id,
          null,
          'error',
          ticket.message,
          { details: ticket.details },
          0
        );

        // Add to retry queue if notification ID provided
        if (notificationId) {
          await addToRetryQueue(
            notificationId,
            userId,
            ticket.message,
            { details: ticket.details }
          );
        }
      }
    }

    // 8. Record deduplication (unless critical)
    if (!critical) {
      await recordDeduplication(userId, type, actualFingerprint);
    }

    // 9. Remove from retry queue if successful
    if (notificationId && tickets.every((t) => t.status === 'ok')) {
      await removeFromRetryQueue(notificationId);
    }

    return {
      success: true,
      sent: true,
      ticketId: tickets[0]?.status === 'ok' ? tickets[0].id : undefined,
    };
  } catch (err) {
    console.error('[pushDelivery] Send push notification exception:', err);

    // Add to retry queue if notification ID provided
    if (notificationId) {
      await addToRetryQueue(
        notificationId,
        userId,
        err instanceof Error ? err.message : 'Unknown error',
        null
      );
    }

    return {
      success: false,
      sent: false,
      error: err instanceof Error ? err.message : 'Unknown error',
    };
  }
}

/**
 * Fetch and process push notification receipts
 * Call this periodically (e.g., every 15 minutes) to update delivery status
 * 
 * @param ticketIds - Array of Expo push ticket IDs to check
 */
export async function processPushReceipts(ticketIds: string[]): Promise<void> {
  if (ticketIds.length === 0) {
    return;
  }

  try {
    const receiptIdChunks = expo.chunkPushNotificationReceiptIds(ticketIds);

    for (const chunk of receiptIdChunks) {
      try {
        const receipts = await expo.getPushNotificationReceiptsAsync(chunk);

        for (const receiptId of Object.keys(receipts)) {
          const receipt = receipts[receiptId];

          // Update delivery log with receipt status
          if (receipt.status === 'ok') {
            // Update log entry
            await supabase
              .from('push_delivery_log' as never)
              .update({
                receipt_status: 'ok',
              } as never)
              .eq('expo_receipt_id', receiptId);
          } else if (receipt.status === 'error') {
            // Log error details
            await supabase
              .from('push_delivery_log' as never)
              .update({
                receipt_status: receipt.details?.error || 'error',
                receipt_message: receipt.message,
                receipt_details: receipt.details,
              } as never)
              .eq('expo_receipt_id', receiptId);

            // If DeviceNotRegistered, mark token as inactive
            if (receipt.details?.error === 'DeviceNotRegistered') {
              await supabase
                .from('push_tokens' as never)
                .delete()
                .eq('token', receiptId); // This won't work directly, need to join via delivery log
            }
          }
        }
      } catch (err) {
        console.error('[pushDelivery] Failed to process receipt chunk:', err);
      }
    }
  } catch (err) {
    console.error('[pushDelivery] Process push receipts exception:', err);
  }
}

/**
 * Retry failed push notifications
 * Call this periodically (e.g., every 5 minutes) to retry failed deliveries
 */
export async function retryFailedDeliveries(): Promise<void> {
  try {
    // Get pending retries from view
    const { data: retries, error } = await supabase
      .from('v_pending_retries' as never)
      .select('*')
      .limit(50); // Process up to 50 retries per run

    if (error) {
      console.error('[pushDelivery] Failed to fetch pending retries:', error);
      return;
    }

    if (!retries || retries.length === 0) {
      return;
    }

    console.log(`[pushDelivery] Processing ${retries.length} failed deliveries...`);

    for (const retry of retries as any[]) {
      try {
        // Re-send notification (with critical=true to bypass checks)
        const result = await sendPushNotification({
          userId: retry.user_id,
          notificationId: retry.notification_id,
          title: retry.title,
          body: retry.body,
          type: retry.type,
          critical: true, // Bypass rate limits and quiet hours for retries
        });

        if (result.success && result.sent) {
          console.log(`[pushDelivery] Successfully retried notification ${retry.notification_id}`);
        } else {
          console.warn(`[pushDelivery] Retry failed for notification ${retry.notification_id}:`, result.error);
        }
      } catch (err) {
        console.error(`[pushDelivery] Exception retrying notification ${retry.notification_id}:`, err);
      }
    }
  } catch (err) {
    console.error('[pushDelivery] Retry failed deliveries exception:', err);
  }
}

/**
 * Test push notification delivery (for manual testing)
 */
export async function sendTestPushNotification(userId: string): Promise<PushDeliveryResult> {
  return sendPushNotification({
    userId,
    title: 'Test Notification',
    body: 'This is a test push notification from the Kids P2P Marketplace app.',
    type: 'test',
    data: {
      screen: 'Home',
    },
    critical: false, // Test with real rate limiting and quiet hours
  });
}

// File: p2p-kids-marketplace/src/services/__tests__/pushDelivery.test.ts
// Unit tests for Push Notification Delivery Engine

import { sendPushNotification, sendTestPushNotification, PushDeliveryOptions } from '../pushDelivery';
import { supabase } from '../../config/supabase';
import { Expo } from 'expo-server-sdk';

// Mock dependencies
jest.mock('../../config/supabase', () => ({
  supabase: {
    rpc: jest.fn(),
    from: jest.fn(() => ({
      select: jest.fn().mockReturnThis(),
      eq: jest.fn().mockReturnThis(),
      update: jest.fn().mockReturnThis(),
      delete: jest.fn().mockReturnThis(),
    })),
  },
}));

jest.mock('expo-server-sdk', () => {
  const mockSendPushNotificationsAsync = jest.fn();
  const mockGetPushNotificationReceiptsAsync = jest.fn();
  const mockIsExpoPushToken = jest.fn((token: string) => token.startsWith('ExponentPushToken'));
  const mockChunkPushNotifications = jest.fn((messages: any[]) => [messages]);
  const mockChunkPushNotificationReceiptIds = jest.fn((ids: string[]) => [ids]);

  return {
    Expo: jest.fn().mockImplementation(() => ({
      sendPushNotificationsAsync: mockSendPushNotificationsAsync,
      getPushNotificationReceiptsAsync: mockGetPushNotificationReceiptsAsync,
      chunkPushNotifications: mockChunkPushNotifications,
      chunkPushNotificationReceiptIds: mockChunkPushNotificationReceiptIds,
    })),
    __setMockSendResult: (result: any) => {
      mockSendPushNotificationsAsync.mockResolvedValue(result);
    },
    __setMockReceiptsResult: (result: any) => {
      mockGetPushNotificationReceiptsAsync.mockResolvedValue(result);
    },
    __getMockSendCalls: () => mockSendPushNotificationsAsync.mock.calls,
    __getMockReceiptsCalls: () => mockGetPushNotificationReceiptsAsync.mock.calls,
    __resetMocks: () => {
      mockSendPushNotificationsAsync.mockReset();
      mockGetPushNotificationReceiptsAsync.mockReset();
      mockChunkPushNotifications.mockImplementation((messages: any[]) => [messages]);
      mockChunkPushNotificationReceiptIds.mockImplementation((ids: string[]) => [ids]);
    },
  };

  // Add static methods
  Object.assign(mockSendPushNotificationsAsync, {
    isExpoPushToken: mockIsExpoPushToken,
  });
});

const mockExpoModule = require('expo-server-sdk') as any;

describe('PushDeliveryService', () => {
  const mockUserId = '123e4567-e89b-12d3-a456-426614174000';
  const mockNotificationId = '123e4567-e89b-12d3-a456-426614174001';
  const mockPushTokenId = '123e4567-e89b-12d3-a456-426614174002';
  const mockExpoPushToken = 'ExponentPushToken[xxxxxxxxxxxxxxxxxxxxxx]';

  beforeEach(() => {
    jest.clearAllMocks();
    mockExpoModule.__resetMocks();

    // Default mock responses
    (supabase.rpc as jest.Mock).mockImplementation((fnName: string, params: any) => {
      switch (fnName) {
        case 'check_push_rate_limit':
          return Promise.resolve({ data: true, error: null });
        case 'is_in_quiet_hours':
          return Promise.resolve({ data: false, error: null });
        case 'is_duplicate_notification':
          return Promise.resolve({ data: false, error: null });
        case 'record_notification_dedup':
          return Promise.resolve({ data: null, error: null });
        case 'log_push_delivery':
          return Promise.resolve({ data: mockPushTokenId, error: null });
        case 'add_to_retry_queue':
          return Promise.resolve({ data: null, error: null });
        case 'remove_from_retry_queue':
          return Promise.resolve({ data: null, error: null });
        default:
          return Promise.resolve({ data: null, error: null });
      }
    });

    // Mock push tokens query
    (supabase.from as jest.Mock).mockReturnValue({
      select: jest.fn().mockReturnThis(),
      eq: jest.fn().mockResolvedValue({
        data: [{ id: mockPushTokenId, token: mockExpoPushToken }],
        error: null,
      }),
      update: jest.fn().mockReturnThis(),
      delete: jest.fn().mockReturnThis(),
    });

    // Mock Expo send success
    mockExpoModule.__setMockSendResult([
      {
        status: 'ok',
        id: 'expo-ticket-id-123',
      },
    ]);
  });

  describe('sendPushNotification', () => {
    it('should send push notification successfully', async () => {
      const options: PushDeliveryOptions = {
        userId: mockUserId,
        notificationId: mockNotificationId,
        title: 'Test Notification',
        body: 'This is a test',
        type: 'test',
      };

      const result = await sendPushNotification(options);

      expect(result.success).toBe(true);
      expect(result.sent).toBe(true);
      expect(result.ticketId).toBe('expo-ticket-id-123');

      // Verify Expo SDK was called
      const sendCalls = mockExpoModule.__getMockSendCalls();
      expect(sendCalls.length).toBe(1);
      expect(sendCalls[0][0][0].title).toBe('Test Notification');
    });

    it('should block duplicate notifications', async () => {
      // Mock duplicate check to return true
      (supabase.rpc as jest.Mock).mockImplementation((fnName: string) => {
        if (fnName === 'is_duplicate_notification') {
          return Promise.resolve({ data: true, error: null });
        }
        return Promise.resolve({ data: false, error: null });
      });

      const options: PushDeliveryOptions = {
        userId: mockUserId,
        title: 'Duplicate Test',
        body: 'This should be blocked',
        type: 'test',
        fingerprint: 'same-fingerprint',
      };

      const result = await sendPushNotification(options);

      expect(result.success).toBe(true);
      expect(result.sent).toBe(false);
      expect(result.duplicate).toBe(true);

      // Verify Expo SDK was NOT called
      const sendCalls = mockExpoModule.__getMockSendCalls();
      expect(sendCalls.length).toBe(0);
    });

    it('should respect rate limits', async () => {
      // Mock rate limit check to return false (rate limited)
      (supabase.rpc as jest.Mock).mockImplementation((fnName: string) => {
        if (fnName === 'check_push_rate_limit') {
          return Promise.resolve({ data: false, error: null });
        }
        return Promise.resolve({ data: false, error: null });
      });

      const options: PushDeliveryOptions = {
        userId: mockUserId,
        title: 'Rate Limited Test',
        body: 'This should be rate limited',
        type: 'test',
      };

      const result = await sendPushNotification(options);

      expect(result.success).toBe(true);
      expect(result.sent).toBe(false);
      expect(result.rateLimited).toBe(true);

      // Verify Expo SDK was NOT called
      const sendCalls = mockExpoModule.__getMockSendCalls();
      expect(sendCalls.length).toBe(0);
    });

    it('should respect quiet hours', async () => {
      // Mock quiet hours check to return true (in quiet hours)
      (supabase.rpc as jest.Mock).mockImplementation((fnName: string) => {
        if (fnName === 'is_in_quiet_hours') {
          return Promise.resolve({ data: true, error: null });
        }
        if (fnName === 'check_push_rate_limit') {
          return Promise.resolve({ data: true, error: null });
        }
        return Promise.resolve({ data: false, error: null });
      });

      const options: PushDeliveryOptions = {
        userId: mockUserId,
        title: 'Quiet Hours Test',
        body: 'This should be deferred',
        type: 'test',
      };

      const result = await sendPushNotification(options);

      expect(result.success).toBe(true);
      expect(result.sent).toBe(false);
      expect(result.inQuietHours).toBe(true);

      // Verify Expo SDK was NOT called
      const sendCalls = mockExpoModule.__getMockSendCalls();
      expect(sendCalls.length).toBe(0);
    });

    it('should bypass checks for critical notifications', async () => {
      // Mock all checks to block
      (supabase.rpc as jest.Mock).mockImplementation((fnName: string) => {
        if (fnName === 'is_in_quiet_hours') {
          return Promise.resolve({ data: true, error: null });
        }
        if (fnName === 'check_push_rate_limit') {
          return Promise.resolve({ data: false, error: null });
        }
        if (fnName === 'is_duplicate_notification') {
          return Promise.resolve({ data: true, error: null });
        }
        return Promise.resolve({ data: null, error: null });
      });

      const options: PushDeliveryOptions = {
        userId: mockUserId,
        title: 'Critical Notification',
        body: 'Payment failed - action required!',
        type: 'payment_failed',
        critical: true, // Should bypass all checks
      };

      const result = await sendPushNotification(options);

      expect(result.success).toBe(true);
      expect(result.sent).toBe(true);

      // Verify Expo SDK was called despite blocks
      const sendCalls = mockExpoModule.__getMockSendCalls();
      expect(sendCalls.length).toBe(1);
    });

    it('should handle no push tokens gracefully', async () => {
      // Mock no push tokens
      (supabase.from as jest.Mock).mockReturnValue({
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockResolvedValue({
          data: [],
          error: null,
        }),
      });

      const options: PushDeliveryOptions = {
        userId: mockUserId,
        title: 'No Token Test',
        body: 'User has no tokens',
        type: 'test',
      };

      const result = await sendPushNotification(options);

      expect(result.success).toBe(false);
      expect(result.sent).toBe(false);
      expect(result.error).toBe('No push tokens registered');
    });

    it('should handle Expo send failure', async () => {
      // Mock Expo send failure
      mockExpoModule.__setMockSendResult([
        {
          status: 'error',
          message: 'DeviceNotRegistered',
          details: { error: 'DeviceNotRegistered' },
        },
      ]);

      const options: PushDeliveryOptions = {
        userId: mockUserId,
        notificationId: mockNotificationId,
        title: 'Send Failure Test',
        body: 'This should fail',
        type: 'test',
      };

      const result = await sendPushNotification(options);

      expect(result.success).toBe(true); // Overall operation succeeded

      // Verify retry queue was called
      expect(supabase.rpc).toHaveBeenCalledWith(
        'add_to_retry_queue',
        expect.objectContaining({
          p_notification_id: mockNotificationId,
          p_user_id: mockUserId,
        })
      );
    });

    it('should log delivery attempts', async () => {
      const options: PushDeliveryOptions = {
        userId: mockUserId,
        notificationId: mockNotificationId,
        title: 'Log Test',
        body: 'Testing delivery logging',
        type: 'test',
      };

      await sendPushNotification(options);

      // Verify log_push_delivery was called
      expect(supabase.rpc).toHaveBeenCalledWith(
