            error: null,
          }),
        };
      }

      return {
        update: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
      };
    });

    (supabase.functions.invoke as jest.Mock).mockResolvedValue({
      data: {
        success: true,
        tickets: [{ status: 'ok', id: 'ticket-1' }],
      },
